890	-- ─────────────────────────────────────────────────────────────────────────────
891	-- 9) tg_movimentacoes_sync_estoque_lotes: motivos de exposição também
892	--    sincronizam estoque_lotes (o lote físico saiu da câmara). Guard
893	--    app.skip_lote_reconcile preservado — única mudança é a lista de motivos.
894	-- ─────────────────────────────────────────────────────────────────────────────
895	
896	CREATE OR REPLACE FUNCTION public.tg_movimentacoes_sync_estoque_lotes()
897	 RETURNS trigger
898	 LANGUAGE plpgsql
899	 SECURITY DEFINER
900	 SET search_path TO 'public'
901	AS $function$
902	BEGIN
903	  IF COALESCE(NEW.motivo,'') NOT IN (
904	       'scanner_lote', 'contagem_caixa', 'ajuste_lote_manual',
905	       'saida_inteira', 'retirada_avulsa', 'adicao_avulsa',
906	       'saida_inteira_exposicao', 'retirada_avulsa_exposicao'
907	     ) THEN
908	    RETURN NEW;
909	  END IF;
910	
911	  IF NEW.lote_id IS NULL OR NEW.produto_master_id IS NULL THEN
912	    RETURN NEW;
913	  END IF;
914	
915	  -- Sinaliza que a alteracao em estoque_lotes veio de uma movimentacao,
916	  -- pra sync_estoque_from_lotes NAO criar lancamento fantasma.
917	  PERFORM set_config('app.skip_lote_reconcile', '1', true);
918	
919	  IF NEW.tipo_movimentacao = 'entrada' THEN
920	    UPDATE public.estoque_lotes
921	       SET quantidade = GREATEST(0, quantidade + NEW.quantidade)
922	     WHERE lote_id = NEW.lote_id
923	       AND produto_id = NEW.produto_master_id
924	       AND loja_id = NEW.loja_id;
925	
926	  ELSIF NEW.tipo_movimentacao = 'saida' THEN
927	    UPDATE public.estoque_lotes
928	       SET quantidade = GREATEST(0, quantidade - NEW.quantidade)
929	     WHERE lote_id = NEW.lote_id
930	       AND produto_id = NEW.produto_master_id
931	       AND loja_id = NEW.loja_id;
932	  END IF;
933	
934	  -- Sem linha pra esse (lote, produto, loja) e e entrada -> cria com a loja correta.
935	  IF NOT FOUND AND NEW.tipo_movimentacao = 'entrada' THEN
936	    INSERT INTO public.estoque_lotes (lote_id, produto_id, loja_id, quantidade)
937	    VALUES (NEW.lote_id, NEW.produto_master_id, NEW.loja_id, NEW.quantidade);
938	  END IF;
939	
940	  RETURN NEW;
941	END;
942	$function$;
